'use strict';
// Independent preview scenarios. Switching them never resets the user's draft.
const dayPreview={mode:'balanced',checks:[true,true,false,false]};
const dayModes={
 balanced:{title:'A little clarity for your day',order:['paperwork','travel','weather'],places:'Places for your afternoon',events:'Something to look forward to'},
 paperwork:{title:'One thing to pick up first',order:['paperwork','travel','weather'],places:'A breather for afterwards',events:'Leave room for something good'},
 travel:{title:'Before you head out',order:['travel','weather','paperwork'],places:'Ideas for when you get there',events:'Make an evening of it'},
 rain:{title:'A small change of plans?',order:['weather','travel','paperwork'],places:'Before you choose an outdoor plan',events:'Plans worth checking before you go'},
 free:{title:'Good to have in the background',order:['weather','travel','paperwork'],places:'A little time to explore',events:'Follow your curiosity'},
};
Object.assign(shapes,{rain:'<path d="M6 15a4 4 0 0 1 0-8 6 6 0 0 1 11-1 4.5 4.5 0 0 1 1 9M8 18l-1 3m6-3-1 3m6-3-1 3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'});
const checkedCount=()=>dayPreview.checks.filter(Boolean).length;
function paperworkGlance(){const count=checkedCount(),needsAttention=dayPreview.mode==='paperwork'&&count<4;return `<article class="glance-item paperwork-glance${needsAttention?' priority':''}" data-glance="paperwork"><div class="glance-label"><span>${icon('document')}Your paperwork</span>${needsAttention?'<b>Pick up here</b>':'<small>Your checklist</small>'}</div><h3>${count===4?'Checklist complete':`${count} of 4 steps checked off`}</h3><div class="check-progress" role="progressbar" aria-label="Sample checklist progress" aria-valuemin="0" aria-valuemax="4" aria-valuenow="${count}">${[0,1,2,3].map(i=>`<span class="${dayPreview.checks[i]?'done':''}"></span>`).join('')}</div><button class="glance-link" data-action="paperwork">${count===4?'Review checklist':'Continue checklist'}${icon('arrow')}</button><small class="data-caption">Sample checklist</small></article>`;}
function travelRows(){const delayed=dayPreview.mode==='travel';return `<div class="departure-row"><span class="route-code">A</span><span class="destination">City centre${delayed?'<small class="delay">Running 5 min later</small>':''}</span><strong>${delayed?'9':'4'}<small> min</small></strong></div><div class="departure-row"><span class="route-code bus">B</span><span class="destination">Central station</span><strong>11<small> min</small></strong></div>`;}
function travelGlance(){const priority=dayPreview.mode==='travel';return `<article class="glance-item travel-glance${priority?' priority':''}" data-glance="travel"><div class="glance-label"><span>${icon('train')}Your connections</span>${priority?'<b>Delay to check</b>':'<small>Nearby stop</small>'}</div>${travelRows()}<button class="glance-link" data-action="departures">See your departures${icon('arrow')}</button><small class="data-caption">Sample · not live</small></article>`;}
function weatherHours(){const rain=dayPreview.mode==='rain';return [['Now',rain?'18°':'21°','sun'],['17:00',rain?'16°':'20°',rain?'rain':'sun'],['20:00',rain?'15°':'18°',rain?'rain':'sun']].map(([time,temp,glyph])=>`<div><span>${time}</span>${icon(glyph)}<strong>${temp}</strong></div>`).join('');}
function weatherGlance(){const rain=dayPreview.mode==='rain';return `<article class="glance-item weather-glance${rain?' priority':''}" data-glance="weather"><div class="glance-label"><span>${icon(rain?'rain':'sun')}The hours ahead</span>${rain?'<b>Rain later</b>':'<small>Weather</small>'}</div><div class="forecast-hours">${weatherHours()}</div><button class="glance-link" data-action="${rain?'weather-prompt':'weather'}">${rain?'Find an indoor idea':'See the forecast'}${icon('arrow')}</button><small class="data-caption">Sample · not live</small></article>`;}
function renderDayOverview(){const completedPreparation=dayPreview.mode==='paperwork'&&checkedCount()===4;const config=completedPreparation?{...dayModes.free,title:'A little more room in your day',reason:'Your sample preparation list is complete. Discovery can move up.'}:dayModes[dayPreview.mode],glance=document.querySelector('#at-a-glance');glance.innerHTML=`<div class="overview-heading"><div><h2 id="glance-title">${config.title}</h2></div><span class="overview-dot" aria-hidden="true"></span></div><div class="glance-content">${config.order.map(kind=>({paperwork:paperworkGlance,travel:travelGlance,weather:weatherGlance})[kind]()).join('')}</div>`;
 const flow=document.querySelector('#day-flow'),discovery=document.querySelector('#discovery-board'),yourDay=document.querySelector('#your-day-overview');
 if(dayPreview.mode==='free'||completedPreparation){flow.append(discovery,glance,yourDay);}else{flow.append(glance,yourDay,discovery);}
 document.querySelector('#places-title').textContent=config.places;document.querySelector('#events-title').textContent=config.events;
 const rain=dayPreview.mode==='rain';document.querySelector('.weather-compact strong').textContent=rain?'18°':'21°';document.querySelector('.weather-compact small').textContent=rain?'Rain later':'Partly sunny';document.querySelector('.weather-compact').setAttribute('aria-label',rain?'Weather, 18 degrees, rain later':'Weather, 21 degrees, partly sunny');document.querySelector('.weather-compact .weather-art').innerHTML=rain?icon('rain'):'<span class="sun"></span><span class="cloud"></span>';
 document.querySelector('#city-note-text').textContent=dayPreview.mode==='travel'?'Departure delay':rain?'Rain later':'City updates';
 document.querySelector('.today-board').dataset.day=dayPreview.mode;
 renderYourDay();renderComposerContext();
}
function renderYourDay(){const ids=state.hasDraft?state.draft:state.saved,el=document.querySelector('#your-day-overview');el.hidden=!ids.length;if(!ids.length)return;el.innerHTML=`<div class="your-day-mark">${icon('bookmark')}</div><div class="your-day-content"><span>${state.hasDraft?'Your draft':'Saved day'}</span><h3>${safe(samples[ids[0]].title)}${ids.length>1?` <small>+ ${ids.length-1} more</small>`:''}</h3></div><button class="day-resume" data-action="day">${state.hasDraft?'Review':'Resume'}${icon('arrow')}</button>`;}
function renderComposerContext(){const el=document.querySelector('#composer-context');el.hidden=!state.draft.length;el.innerHTML=state.draft.length?`<span class="context-intro">With these ideas</span><div class="context-scroll">${state.draft.map(id=>`<button data-unkeep="${id}" aria-label="Remove ${safe(samples[id].title)} from your choices">${safe(samples[id].title)}${icon('close')}</button>`).join('')}</div>`:'';document.body.classList.toggle('has-idea-context',state.draft.length>0);}
const updateCountBeforeOverview=updateCount;
updateCount=function(){updateCountBeforeOverview();renderYourDay();renderComposerContext();};
function preparePrompt(text){if(!input.value.trim()){input.value=text;input.dispatchEvent(new Event('input'));}if(sheet.open)sheet.close();input.focus();toast('Ready to compose');}
function showChecklist(){openSheet('Your personal checklist',`<p>Sample preparation · not legal requirements</p><div class="checklist-sample">${['Notes saved','Files added','Checklist reviewed','Follow-up noted'].map((label,i)=>`<label><input type="checkbox" data-check-step="${i}"${dayPreview.checks[i]?' checked':''}><span>${label}</span></label>`).join('')}</div><div class="checklist-summary"><strong id="checklist-count">${checkedCount()} of 4 checked off</strong><span>Personal preparation</span></div><p class="legal-boundary">Legal status not assessed</p>`);}
function showDepartures(){openSheet('Your next connections',`<p>Example stop</p><div class="sheet-departures">${travelRows()}</div><div class="sheet-actions">${button('Plan a journey','travel-prompt',true)}</div><p class="legal-boundary">Sample departures · not live</p>`);}
function showForecast(){openSheet('The hours ahead',`<div class="forecast-hours sheet-forecast">${weatherHours()}</div><div class="sheet-actions">${button('Plan around the weather','weather-prompt',true)}</div><p class="legal-boundary">Sample forecast · not live</p>`);}
const actionBeforeOverview=action;
action=function(name){if(name==='paperwork'){showChecklist();return;}if(name==='departures'){showDepartures();return;}if(name==='weather'){showForecast();return;}if(name==='weather-prompt'){preparePrompt(dayPreview.mode==='rain'?'I’d like an indoor idea for a rainy afternoon.':'I’d like to spend some time outdoors today.');return;}if(name==='travel-prompt'){preparePrompt('How do I get to the city centre?');return;}if(name==='updates'){openSheet('What might affect your day',dayPreview.mode==='travel'?`<p>Sample departure delay</p>${button('See departures','departures',true)}`:dayPreview.mode==='rain'?`<p>Sample forecast: rain later</p>${button('See forecast','weather',true)}`:`<p>No sample alerts</p>`);return;}actionBeforeOverview(name);};
// Kept items accompany a request without replacing the user's words.
const composeBeforeOverview=compose;
compose=async function(raw){const text=raw.trim();if(/\b(no|not|avoid|without)\b|\d+\s*(km|minutes?|mins?)|\d{1,2}:\d{2}/i.test(text)){await composeBeforeOverview(raw);return;}if(/\bindoor\b/i.test(text)){state.kind=null;state.filter='indoor';state.request=text;input.value=text;input.blur();state.version++;state.busy=false;document.querySelector('.compose-submit').disabled=false;openComposer();question('Let’s keep it indoors.','The sample catalogue here contains outdoor ideas. We would need a verified indoor option to meet your request.',button('Edit my request','edit-request',true));return;}if(text&&state.draft.length&&/\b(this|these|them|fit|afterwards|nearby|plan)\b/i.test(text)){state.request=text;input.value=text;input.blur();state.version++;state.busy=false;document.querySelector('.compose-submit').disabled=false;renderPlan();conversation.insertAdjacentHTML('afterbegin',echo());return;}await composeBeforeOverview(raw);};
document.querySelector('#preview-day').addEventListener('change',event=>{dayPreview.mode=event.target.value;renderDayOverview();});
document.addEventListener('change',event=>{if(event.target.matches('[data-check-step]')){dayPreview.checks[Number(event.target.dataset.checkStep)]=event.target.checked;document.querySelector('#checklist-count').textContent=`${checkedCount()} of 4 checked off`;renderDayOverview();}});
document.addEventListener('click',event=>{const target=event.target.closest('[data-unkeep]');if(target&&state.draft.includes(target.dataset.unkeep))keep(target.dataset.unkeep);});
renderDayOverview();
